public long findMinimumWeightWalk(int N, int[][] edges) {
    // Initialize graph representation
    long[][] graph = new long[N][N];
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            graph[i][j] = Long.MAX_VALUE;
        }
    }
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        int w = edge[2];
        graph[u][v] = Math.min(graph[u][v], w);
    }

    // Check if all vertices are reachable
    boolean[] visited = new boolean[N];
    dfs(0, visited, graph);
    for (boolean v : visited) {
        if (!v) return -1;
    }

    // Use Floyd-Warshall to find the shortest paths between all pairs of vertices
    long[][] dist = new long[N][N];
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            dist[i][j] = graph[i][j];
        }
        dist[i][i] = 0;
    }
    for (int k = 0; k < N; k++) {
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (dist[i][k] != Long.MAX_VALUE && dist[k][j] != Long.MAX_VALUE) {
                    dist[i][j] = Math.min(dist[i][j], dist[i][k] + dist[k][j]);
                }
            }
        }
    }

    // Calculate the minimum weight walk
    long minWeight = Long.MAX_VALUE;
    for (int i = 0; i < N; i++) {
        long totalWeight = 0;
        for (int j = 0; j < N; j++) {
            if (dist[i][j] == Long.MAX_VALUE) {
                totalWeight = Long.MAX_VALUE;
                break;
            }
            totalWeight += dist[i][j];
        }
        minWeight = Math.min(minWeight, totalWeight);
    }

    return minWeight == Long.MAX_VALUE ? -1 : minWeight;
}

private void dfs(int node, boolean[] visited, long[][] graph) {
    visited[node] = true;
    for (int i = 0; i < graph.length; i++) {
        if (graph[node][i] != Long.MAX_VALUE && !visited[i]) {
            dfs(i, visited, graph);
        }
    }
}
